import{_ as r,C as s,c as l,o as c,ag as i,j as o,G as n,a}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"WooCommerce Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/woocommerce-integration-with-fluentaffiliate.md","filePath":"guide/integrations/woocommerce-integration-with-fluentaffiliate.md","lastUpdated":1755766981000}'),u={name:"guide/integrations/woocommerce-integration-with-fluentaffiliate.md"};function f(g,e,m,p,d,h){const t=s("ZoomableImage");return c(),l("div",null,[e[0]||(e[0]=i('<h1 id="woocommerce-integration-with-fluentaffiliate" tabindex="-1">WooCommerce Integration with FluentAffiliate <a class="header-anchor" href="#woocommerce-integration-with-fluentaffiliate" aria-label="Permalink to &quot;WooCommerce Integration with FluentAffiliate&quot;">​</a></h1><p>WooCommerce is one of the most popular e-commerce plugins for WordPress, helping you build and manage a powerful online store. When you connect WooCommerce with FluentAffiliate, you can launch a full-featured affiliate program to boost your sales, track commissions, and manage affiliate payments with ease.</p><p>This guide will walk you through every step of integrating WooCommerce with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>WooCommerce is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, you first need to have the WooCommerce plugin installed and activated on your WordPress website.</p></div><h2 id="enable-the-woocommerce-integration" tabindex="-1">Enable the WooCommerce Integration <a class="header-anchor" href="#enable-the-woocommerce-integration" aria-label="Permalink to &quot;Enable the WooCommerce Integration&quot;">​</a></h2><p>The first step is to activate the WooCommerce module within your FluentAffiliate settings. Once Woocommerce is running on your site, you can connect it to FluentAffiliate.</p><ol><li>Go to your <strong>FluentAffiliate Dashboard</strong> and click on the <strong>Settings</strong> tab in the top menu.</li><li>From the menu on the left, select <strong>Integration Settings</strong>.</li><li>You will see a list of available integrations. Find <strong>WooCommerce</strong> and click the <strong>toggle</strong> button next to it to turn it on.</li></ol><p>Your WooCommerce integration is now active, allowing affiliates to earn referral commissions on your products.</p><p>Once the toggle is active, a <strong>Manage</strong> link will appear. Click this link to configure your WooCommerce-specific affiliate settings.</p>',9)),o("p",null,[n(t,{src:"/guide/public/images/integrations/woocommerce/integration-setup-options.webp",alt:"Integration Settings"})]),e[1]||(e[1]=i('<h2 id="configure-woocommerce-settings" tabindex="-1">Configure WooCommerce Settings <a class="header-anchor" href="#configure-woocommerce-settings" aria-label="Permalink to &quot;Configure WooCommerce Settings&quot;">​</a></h2><p>In the management panel, you can fine-tune how commissions work for your WooCommerce store.</p><p>Here are the available options:</p><ul><li><strong>Enable Affiliate Integration for Woocommerce:</strong> This checkbox acts as the master switch for the integration. Ensure it is checked.</li><li><strong>Enable Branded Coupon Codes for affiliates:</strong> When you enable this, you can offer branded coupon codes to your affiliates. This allows them to promote products with unique discount codes, giving them another powerful marketing tool. You can manage these codes in the <strong>Discount Codes</strong> editor in WooCommerce.</li></ul>',4)),o("p",null,[n(t,{src:"/guide/public/images/integrations/woocommerce/enable-branded-coupon-code.webp",alt:"Branded Coupon Code"})]),e[2]||(e[2]=i('<p>For example, this is perfect if you want to give a special coupon code to a social media influencer who is also one of your affiliates.To assign a coupon to a specific affiliate, follow these steps:</p><ol><li><p>From your WordPress dashboard, navigate to <strong>Marketing</strong> &gt; <strong>Coupon Data</strong>.</p></li><li><p>You can either create a new coupon or edit an existing one.</p></li><li><p>On the coupon editor page, scroll down to find the <strong>FluentAffiliate Coupon</strong> section.</p></li><li><p>Click on the dropdown field and select the <strong>affiliate&#39;s</strong> name from the list.</p></li><li><p><strong>Save</strong> the coupon. Now, when this coupon is used for a purchase, the selected affiliate will automatically be credited with the referral.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Before you can assign a coupon, the user must already be an approved affiliate in your FluentAffiliate program.</p></div>',3)),o("p",null,[n(t,{src:"/guide/public/images/integrations/woocommerce/woocommerce-fluentaffiliate-coupon.webp",alt:"Branded Coupon Code"})]),e[3]||(e[3]=o("ul",null,[o("li",null,[o("strong",null,"Enable custom rate for specific product or categories:"),a(" This is a powerful feature that lets you override your default commission rate. Check this box if you want to set special commission rates for specific products or entire product categories.")])],-1)),e[4]||(e[4]=o("p",null,[a("After that, click on the "),o("strong",null,"+Add New Group"),a(" button. You will find options to choose how you want to apply this custom rate. You can set it for specific individual products or for entire product categories.")],-1)),o("p",null,[n(t,{src:"/guide/public/images/integrations/woocommerce/configure-woocommerce-settings.webp",alt:"Integration Settings"})]),e[5]||(e[5]=i('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This feature gives you the flexibility to offer different commission rates for different products. For example, you could offer a higher commission on a new product as an incentive for affiliates to promote it more heavily.</p></div><ul><li><p><strong>Select Products:</strong> In the Select field, begin typing the name of the product you want to set a custom rate for and choose it from the list.</p></li><li><p><strong>Select Rate:</strong> Enter the new commission value (e.g., 20 for 20% or $20). Next, use the dropdown menu to choose if the rate is a Percentage (%) of the sale or a Fixed dollar amount.</p></li><li><p><strong>Save Settings:</strong> Once you have configured all your custom rates, click the <strong>Save Settings</strong> button to make them live.</p></li></ul><p>You can select multiple custom rate types for products or categories by clicking the <strong>+ Add New Group</strong> button. Also, you can delete the affiliate rates by clicking the delete icon in the top right corner.</p>',3)),o("p",null,[n(t,{src:"/guide/public/images/integrations/woocommerce/select-product-rate.webp",alt:"Integration Settings"})]),e[6]||(e[6]=i('<h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>Once you&#39;ve finished setting up your <strong>Woocommerce</strong> product settings, it&#39;s time to generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a>.</p><p>Whenever a customer makes a purchase through this link, the affiliate will earn a commission based on the rates you’ve set up.</p><h2 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h2><p>If you encounter any issues, here are some solutions to common problems:</p><ul><li><p><strong>Affiliate Links Not Generating:</strong> Verify that the product URL you are using is correct and the page is publicly accessible.</p></li><li><p><strong>Conflicting Rates:</strong> If a product-specific rate isn&#39;t being applied as expected, review your rules to ensure there isn&#39;t an overlap with a category-wide rate that might be taking precedence.</p></li></ul>',6))])}const _=r(u,[["render",f]]);export{b as __pageData,_ as default};
